package engine

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"strings"
	"sync"
)

//go:embed data/themes.json
var themeData []byte

// Swatches are generated by loading each theme in real Neovim; see integration_test.go.
//
//go:embed data/theme-swatches.json
var swatchData []byte

// Theme is one color scheme family; Plugin is empty for themes built into Neovim.
type Theme struct {
	ID       string         `json:"id"`
	Label    string         `json:"label"`
	Plugin   string         `json:"plugin,omitempty"`
	Detail   string         `json:"detail,omitempty"`
	Hidden   bool           `json:"hidden,omitempty"`
	Variants []ThemeVariant `json:"variants"`
}

// ThemeVariant is what appearance.colorscheme stores. Before runs ahead of
// :colorscheme for themes that select a style through settings.
type ThemeVariant struct {
	ID            string   `json:"id"`
	Label         string   `json:"label"`
	Colorscheme   string   `json:"colorscheme"`
	Background    string   `json:"background,omitempty"`
	SetBackground bool     `json:"set_background,omitempty"`
	Before        string   `json:"before,omitempty"`
	Swatch        []string `json:"swatch,omitempty"`
}

const CustomTheme = "custom"

var (
	themesOnce sync.Once
	themeList  []Theme
)

// Themes lists every theme, plugin themes first, in catalog order.
func Themes() []Theme {
	themesOnce.Do(func() {
		var data struct {
			Themes []Theme `json:"themes"`
		}
		if err := json.Unmarshal(themeData, &data); err != nil {
			panic(err)
		}
		var swatches map[string][]string
		if err := json.Unmarshal(swatchData, &swatches); err != nil {
			panic(err)
		}
		for i := range data.Themes {
			for j := range data.Themes[i].Variants {
				v := &data.Themes[i].Variants[j]
				if len(v.Swatch) == 0 {
					v.Swatch = swatches[v.ID]
				}
			}
		}
		themeList = data.Themes
	})
	return themeList
}

// ThemeFor finds the theme and variant stored in appearance.colorscheme.
func ThemeFor(value string) (Theme, ThemeVariant, bool) {
	for _, t := range Themes() {
		for _, v := range t.Variants {
			if v.ID == value {
				return t, v, true
			}
		}
	}
	return Theme{}, ThemeVariant{}, false
}

func themeChoices() []string {
	var out []string
	for _, t := range Themes() {
		for _, v := range t.Variants {
			out = append(out, v.ID)
		}
	}
	return append(out, CustomTheme)
}

func validateCustomTheme(s State) error {
	repo, _ := s.Values["appearance.custom_theme.repository"].(string)
	rev, _ := s.Values["appearance.custom_theme.revision"].(string)
	name, _ := s.Values["appearance.custom_theme.colorscheme"].(string)
	if Value(s, "appearance.colorscheme", "") != CustomTheme {
		if repo != "" || rev != "" || name != "" {
			return fmt.Errorf("custom theme details are set but appearance.colorscheme is not %q", CustomTheme)
		}
		return nil
	}
	if !repositoryPattern.MatchString(repo) {
		return fmt.Errorf("custom theme repository must look like owner/name")
	}
	if !revisionPattern.MatchString(rev) {
		return fmt.Errorf("custom theme revision must be a full 40-character commit")
	}
	if !colorschemePattern.MatchString(name) {
		return fmt.Errorf("custom theme colorscheme name is invalid")
	}
	return nil
}

// themePlugin is the plugin a colorscheme value needs, if any.
func themePlugin(s State) string {
	value, _ := Value(s, "appearance.colorscheme", "").(string)
	if value == CustomTheme {
		return customThemeID
	}
	if t, _, ok := ThemeFor(value); ok {
		return t.Plugin
	}
	return ""
}

func colorschemeLua(s State) string {
	value, ok := s.Values["appearance.colorscheme"].(string)
	if !ok {
		return ""
	}
	name, label, before, background := "", "", "", ""
	plugin := value == CustomTheme
	if plugin {
		name, _ = s.Values["appearance.custom_theme.colorscheme"].(string)
		label, _ = s.Values["appearance.custom_theme.repository"].(string)
	} else {
		t, v, found := ThemeFor(value)
		if !found {
			return ""
		}
		name, label, before, plugin = v.Colorscheme, t.Label, v.Before, t.Plugin != ""
		if v.SetBackground {
			background = v.Background
		}
	}
	var b strings.Builder
	if !plugin {
		if background != "" {
			fmt.Fprintf(&b, "vim.o.background = %s\n", LuaString(background))
		}
		fmt.Fprintf(&b, "vim.cmd.colorscheme(%s)\n", LuaString(name))
		return b.String()
	}
	// A plugin theme may still be downloading; keep a built-in theme until it is there.
	// The background is set after that fallback, which itself forces a dark background.
	fmt.Fprintf(&b, "vim.cmd.colorscheme('habamax')\nif not vim.g.shoshinvim_probe then\n")
	if background != "" {
		fmt.Fprintf(&b, "  vim.o.background = %s\n", LuaString(background))
	}
	if before != "" {
		fmt.Fprintf(&b, "  pcall(function() %s end)\n", before)
	}
	fmt.Fprintf(&b, "  if not pcall(vim.cmd.colorscheme, %s) then\n    vim.schedule(function() vim.notify(%s, vim.log.levels.WARN) end)\n  end\nend\n",
		LuaString(name), LuaString(label+" is not installed yet; using habamax. Open ShoshinVim and download plugins."))
	return b.String()
}
